   match('الكلمة وصفّها', [('ننتقل إلى', 'صفّ القاعة: انتقال'), ('باختصار', 'صفّ القاعة: خلاصة'), ('هل يمكن أن', 'صفّ الهاتف: طلب'), ('تمّ التسجيل', 'صفّ الهاتف: جواب الموظّف')]),
   match('الفعل بعد أن', [('أودّ أن', 'أغيّرَ'), ('هل يمكن أن', 'تشرحَ'), ('يجب أن', 'يكونَ'), ('هل يمكن أن (لجماعة)', 'تكرّروا')]),
   order('رتّب مقدّمة يوسف', ['سأتكلّم', 'عن', 'الفاتورة', 'في', 'ثلاث', 'نقاط.']),
   order('رتّب طلب أحمد', ['أودّ', 'أن', 'أسألَ', 'عن', 'تغطية', 'الزجاج.']),
   order('رتّب جواب سالم', ['تمّ', 'تسجيل', 'الطلب', 'برقم', 'ثلاثة', 'ثلاثة', 'خمسة', 'ثمانية.']),
   pic('«أتّصل بخصوص وثيقة التأمين»', ['phone', 'letter', 'book'], 0),
   pic('«التوقيع بالقلم لا بالختم»', ['pen', 'pens', 'form'], 0),
   pic('«تغطية الزجاج بعد مئتي ريال»', ['car', 'window', 'house'], 0),
   cloze('أكمل صفّ القاعة', '___ عن الفاتورة في ثلاث نقاط. أوّلًا الرقم. ___ إلى التاريخ. ___ التوقيع فبالقلم. باختصار، فاتورة بلا هذه الثلاثة ورقة.', ['سأتكلّم', 'ننتقل', 'أمّا'], ['أتّصل', 'إذن']),
   cloze('أكمل صفّ الهاتف', 'السلام عليكم. ___ بخصوص وثيقة التأمين. ___ أن أسأل عن التغطية. هل ___ أن تشرح لي؟', ['أتّصل', 'أودّ', 'يمكن'], ['سأتكلّم', 'يجب']),
   cloze('أكمل الفتحة', 'أودّ أن ___ الموعد، وهل يمكن أن ___ الرقم، ويجب أن ___ التوقيع بالقلم.', ['أغيّرَ', 'تكرّرَ', 'يكونَ'], ['أغيّرُ', 'يكونُ']),
   cloze('أكمل جواب الشركة', '___ تسجيل الطلب برقم ثلاثة ثلاثة خمسة ثمانية، و___ إليك ملخّص ___ برسالة.', ['تمّ', 'سيُرسَل', 'التغطية'], ['كان', 'أرسل']),
   tf('قالت هند إنّ الموظّف يتكلّم بـأنا مثل الزبون.', 'الأستاذة هند: جملتها مبنيّة للمجهول دائمًا: سيُرسَل، تمّ التسجيل؛ لأنّ الشركة تتكلّم لا سالم. أمّا أنتم فتتكلّمون بـأنا.', 'false', 'العكس: الموظّف بالمبنيّ للمجهول، والزبون بـأنا.'),
   tf('رقم طلب أحمد ثلاثة ثلاثة خمسة ثمانية.', 'سالم: تمّ تسجيل الطلب برقم ثلاثة ثلاثة خمسة ثمانية.', 'true', 'نعم، وأعادته كلير رقمًا رقمًا في آخر الدرس.'),
   tf('دفع أحمد مئتي ريال في الدرس.', 'سالم: الزجاج مغطّى بنسبة مئة بالمئة بعد دفع مئتي ريال.', 'ng', 'هذا شرط التغطية في المكالمة التمثيلية؛ ولم يدفع أحد شيئًا في الصفّ.'),
   tap('المس كلمة الانتقال', ['أوّلًا', 'الرقم.', 'ننتقل', 'إلى', 'التاريخ.', 'باختصار'], 'ننتقل'),
   tap('المس كلمة الطلب', ['أتّصل', 'بخصوص', 'الحجز.', 'أودّ', 'أن', 'أغيّرَ', 'الموعد'], 'أودّ'),
   tap('المس الفعل المبنيّ للمجهول', ['تمّ', 'التسجيل', 'وسيُرسَل', 'إليك', 'الملخّص', 'غدًا'], 'وسيُرسَل'),
